arguments.content:
import os
import sys
import re
import urllib.parse
import json
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta, timezone
import dateutil.parser
import subprocess

# Resolve project config
# We can use workspace-orchestrator's project_config.py to load the active project config.
sys.path.insert(0, "/home/bhard/.openclaw/workspace-orchestrator/skills/pipeline")
try:
    import project_config as pc
    cfg = pc.load_project_config()
    print(f"Loaded project config for: {cfg.slug}")
except Exception as e:
    print(f"Error loading project config, fallback to default: {e}")
    cfg = None

# Output config
OUTPUT_FILE = os.environ.get("OUTPUT_FILE", "/tmp/crypto-run-20260604-055346/research/headlines.json")
TARGET_COUNT = int(os.environ.get("TARGET_COUNT", "10"))

# Feeds and priority order from config
if cfg:
    exclude_keywords = cfg.get_path("research.exclude_keywords", [])
    source_priority_order = cfg.get_path("research.source_priority_order", [])
    # Convert list to dict mapping name -> index (lower index = higher priority)
    SOURCE_PRIORITY = {name: idx for idx, name in enumerate(source_priority_order, 1)}
else:
    exclude_keywords = []
    SOURCE_PRIORITY = {}

# Use 99 as fallback priority
def get_source_priority(name):
    # exact match
    if name in SOURCE_PRIORITY:
        return SOURCE_PRIORITY[name]
    # partial match
    for k, v in SOURCE_PRIORITY.items():
        if k.lower() in name.lower() or name.lower() in k.lower():
            return v
    return 99

# Clean and decode helpers
def clean_html(text):
    if not text:
        return ""
    # Strip HTML tags
    clean = re.compile(r'<[^>]+>')
    text = clean.sub('', text)
    # Decode XML/HTML entities
    import html
    text = html.unescape(text)
    return text.strip()

def strip_google_redirect(url):
    if "news.google.com" in url or "/rss/articles/" in url:
        try:
            cmd = ["python3", "/home/bhard/.openclaw/workspace-researcher/skills/research-check/resolve_url.py", url]
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
            resolved = res.stdout.strip()
            if resolved and "RESOLVE_FAILED" not in resolved:
                return resolved
        except Exception as e:
            print(f"Error resolving {url}: {e}")
        return None  # Unresolved aggregator links must be dropped
    return url

# Time boundary: last 24 hours
now = datetime.now(timezone.utc)
time_boundary = now - timedelta(hours=24)

all_items = []

print("Parsing feeds from /tmp/feeds...")
feed_dir = "/tmp/feeds"
if not os.path.exists(feed_dir):
    print(f"Error: {feed_dir} does not exist.")
    sys.exit(1)

# List all xml files in /tmp/feeds
xml_files = sorted([f for f in os.listdir(feed_dir) if f.endswith(".xml")])

for xml_file in xml_files:
    prefix = xml_file.split(".")[0]
    xml_path = os.path.join(feed_dir, xml_file)
    source_path = os.path.join(feed_dir, f"{prefix}.source")

    if os.path.exists(source_path):
        with open(source_path, 'r', encoding='utf-8') as sf:
            source_name = sf.read().strip()
    else:
        source_name = "Unknown"

    try:
        with open(xml_path, 'rb') as f:
            xml_content = f.read()

        # Try to parse XML
        try:
            root = ET.fromstring(xml_content)
        except ET.ParseError as pe:
            # If parse error, try parsing with a regex or basic fix for common XML issues
            # sometimes there are control characters or bad namespace declarations
            # Let's try to strip invalid characters
            xml_str = xml_content.decode('utf-8', errors='ignore')
            # remove some common bad characters
            xml_str = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f-\xff]', '', xml_str)
            try:
                root = ET.fromstring(xml_str.encode('utf-8'))
            except Exception as e2:
                print(f"Error parsing xml {xml_file} ({source_name}): {e2}")
                continue

        items = root.findall('.//item') or root.findall('.//entry')
        if not items:
            # Try atom namespace
            namespaces = {'atom': 'http://www.w3.org/2005/Atom', 'default': 'http://purl.org/rss/1.0/'}
            items = root.findall('.//atom:entry', namespaces) or root.findall('.//default:item', namespaces)

        feed_item_count = 0
        for item in items:
            title_node = item.find('title') or item.find('{http://www.w3.org/2005/Atom}title')
            link_node = item.find('link') or item.find('{http://www.w3.org/2005/Atom}link')

            pub_date_node = None
            for tag in ['pubDate', '{http://www.w3.org/2005/Atom}published', '{http://www.w3.org/2005/Atom}updated', 'published', 'updated', '{http://purl.org/dc/elements/1.1/}date']:
                node = item.find(tag)
                if node is not None:
                    pub_date_node = node
                    break

            desc_node = None
            for tag in ['description', 'summary', '{http://www.w3.org/2005/Atom}summary']:
                node = item.find(tag)
                if node is not None:
                    desc_node = node
                    break

            headline = clean_html(title_node.text) if title_node is not None and title_node.text else ""

            # Extract link
            url = ""
            if link_node is not None:
                if link_node.text:
                    url = link_node.text.strip()
                elif 'href' in link_node.attrib:
                    url = link_node.attrib['href'].strip()

            if not url:
                # Try finding link via atom namespace or children
                for child in item:
                    if 'link' in child.tag or child.tag.endswith('link'):
                        if child.text:
                            url = child.text.strip()
                        elif 'href' in child.attrib:
                            url = child.attrib['href'].strip()
                        if url:
                            break

            if not headline or not url:
                continue

            url = strip_google_redirect(url)
            if not url:
                # Dropped aggregator link
                continue

            # Pub Date
            pub_date_str = ""
            if pub_date_node is not None and pub_date_node.text:
                pub_date_str = pub_date_node.text.strip()

            # Parse Pub Date
            parsed_date = None
            if pub_date_str:
                try:
                    parsed_date = dateutil.parser.parse(pub_date_str)
                    if parsed_date.tzinfo is None:
                        parsed_date = parsed_date.replace(tzinfo=timezone.utc)
                    else:
                        parsed_date = parsed_date.astimezone(timezone.utc)
                except Exception:
                    pass

            # Description / summary
            summary = ""
            if desc_node is not None and desc_node.text:
                summary = clean_html(desc_node.text)
            else:
                # Try content encoded or similar
                content_encoded = item.find('{http://purl.org/rss/1.0/modules/content/}encoded')
                if content_encoded is not None and content_encoded.text:
                    summary = clean_html(content_encoded.text)

            # Trim summary to 280 chars
            if summary:
                summary = summary[:280]
                if len(summary) == 280:
                    summary += "..."

            if url.startswith("mailto:") or url.startswith("javascript:"):
                continue

            # Date filter: within 24 hours. If pub date parsing fails, keep only if it is within first 5 items of feed
            keep_by_date = False
            if parsed_date:
                if parsed_date >= time_boundary:
                    keep_by_date = True
            else:
                if feed_item_count < 5:
                    keep_by_date = True

            if not keep_by_date:
                continue

            # Exclude keywords filter
            headline_lower = headline.lower()
            is_excluded = False
            for kw in exclude_keywords:
                if kw.lower() in headline_lower:
                    is_excluded = True
                    break
            if is_excluded:
                print(f"Skipping article due to exclude_keywords: {headline}")
                continue

            all_items.append({
                "headline": headline,
                "url": url,
                "pub_date": parsed_date.isoformat() if parsed_date else datetime.now(timezone.utc).isoformat(),
                "parsed_date_obj": parsed_date if parsed_date else datetime.now(timezone.utc),
                "source": source_name,
                "summary": summary,
                "corroborating_sources": []
            })
            feed_item_count += 1

    except Exception as e:
        print(f"Error reading/parsing feed {xml_file} ({source_name}): {e}")

print(f"Total raw items gathered: {len(all_items)}")

# Let's clean up duplicate URLs first
unique_url_items = {}
for item in all_items:
    url = item["url"]
    if url not in unique_url_items:
        unique_url_items[url] = item
    else:
        # Keep the one with higher priority source
        existing = unique_url_items[url]
        if get_source_priority(item["source"]) < get_source_priority(existing["source"]):
            # Move corroborating sources if any
            item["corroborating_sources"].extend(existing["corroborating_sources"])
            if existing["source"] != item["source"]:
                item["corroborating_sources"].append({"source": existing["source"], "url": existing["url"]})
            unique_url_items[url] = item
        else:
            if existing["source"] != item["source"]:
                existing["corroborating_sources"].append({"source": item["source"], "url": item["url"]})

items_after_url_dedupe = list(unique_url_items.values())
print(f"After URL deduplication: {len(items_after_url_dedupe)}")

# Group by near-identical headlines (>= 80% token overlap)
def get_tokens(text):
    text_clean = re.sub(r'[^\w\s]', '', text.lower())
    tokens = set(text_clean.split())
    # Remove some common stop words
    stop_words = {"the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "with", "by", "of", "is", "are", "was", "were", "be", "been", "has", "have", "had"}
    tokens = tokens - stop_words
    return tokens

def is_near_duplicate(item1, item2):
    tokens1 = get_tokens(item1["headline"])
    tokens2 = get_tokens(item2["headline"])
    if not tokens1 or not tokens2:
        return False
    intersection = tokens1.intersection(tokens2)
    union = tokens1.union(tokens2)
    overlap = len(intersection) / min(len(tokens1), len(tokens2))
    return overlap >= 0.8

# Same-story dedupe (using near-identical headlines)
deduped_items = []
for item in items_after_url_dedupe:
    found_duplicate = False
    for existing in deduped_items:
        if is_near_duplicate(item, existing):
            found_duplicate = True
            # Merge corroborating sources (up to 2)
            if len(existing["corroborating_sources"]) < 2:
                existing["corroborating_sources"].append({"source": item["source"], "url": item["url"]})
            # If current item has higher source priority, swap them but keep the corroborating sources
            if get_source_priority(item["source"]) < get_source_priority(existing["source"]):
                # swap primary details but preserve the corroborating sources we're collecting
                old_existing_source = existing["source"]
                old_existing_url = existing["url"]

                existing["headline"] = item["headline"]
                existing["url"] = item["url"]
                existing["pub_date"] = item["pub_date"]
                existing["parsed_date_obj"] = item["parsed_date_obj"]
                existing["source"] = item["source"]
                existing["summary"] = item["summary"]

                # Make sure we don't exceed 2 corroborating sources
                if old_existing_source != existing["source"]:
                    if len(existing["corroborating_sources"]) < 2:
                        existing["corroborating_sources"].append({"source": old_existing_source, "url": old_existing_url})
            break

    if not found_duplicate:
        deduped_items.append(item)

print(f"After headline deduplication: {len(deduped_items)}")

# Step 4 - Persistent dedup gate (URL history)
surviving_candidates = []
for item in deduped_items:
    url = item["url"]
    try:
        # Run history check
        cmd = ["bash", "/home/bhard/.openclaw/workspace-researcher/skills/history/article_history.sh", "check", url]
        res = subprocess.run(cmd, capture_output=True, text=True, check=True)
        status = res.stdout.strip()
        if "NOT_FOUND" in status:
            surviving_candidates.append(item)
        else:
            print(f"Skipping already processed URL: {url}")
    except Exception as e:
        print(f"Error checking history for {url}: {e}")
        # Default to keeping if check fails, to be safe
        surviving_candidates.append(item)

print(f"After history check: {len(surviving_candidates)}")

# Order by pub_date desc
surviving_candidates.sort(key=lambda x: x["parsed_date_obj"], reverse=True)

# Step 5 - Trim to TARGET_COUNT and write JSON
final_list = []
for idx, item in enumerate(surviving_candidates[:TARGET_COUNT]):
    final_list.append({
        "candidate_index": idx + 1,
        "headline": item["headline"],
        "url": item["url"],
        "pub_date": item["pub_date"],
        "source": item["source"],
        "summary": item["summary"],
        "corroborating_sources": item["corroborating_sources"][:2]
    })

if not final_list:
    output_data = {
        "status": "error",
        "reason": "no_candidates"
    }
else:
    output_data = {
        "status": "ok",
        "mode": "headline_scan",
        "scanned_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        "target_count": TARGET_COUNT,
        "candidate_count": len(final_list),
        "candidates": final_list
    }

os.makedirs(os.path.dirname(OUTPUT_FILE), exist_ok=True)
with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
    json.dump(output_data, f, indent=2, ensure_ascii=False)

print(f"Wrote {len(final_list)} candidates to {OUTPUT_FILE}")

